Object.assign(window.DYLEAN_DATA.files["Library/Lean/Data/LOption.lean"],{"text":"/-\nCopyright (c) 2019 Microsoft Corporation. All rights reserved.\nReleased under Apache 2.0 license as described in the file LICENSE.\nAuthors: Leonardo de Moura\n-/\nmodule\n\nprelude\npublic import Init.Data.String.Basic\n\npublic section\nuniverse u\n\nopen Lean\n\nnamespace Lean\n\ninductive LOption (α : Type u) where\n  | none  : LOption α\n  | some  : α → LOption α\n  | undef : LOption α\n  deriving Inhabited, BEq\n\ninstance [ToString α] : ToString (LOption α) where\n  toString\n    | .none   => \"none\"\n    | .undef  => \"undef\"\n    | .some a => \"(some \" ++ toString a ++ \")\"\n\ndef LOption.toOption : LOption α → Option α\n  | .some a => .some a\n  | _ => .none\n\ndef Option.toLOption {α : Type u} : Option α → LOption α\n  | none   => .none\n  | some a => .some a\n\n@[inline] def toLOptionM {α} {m : Type → Type} [Monad m] (x : m (Option α)) : m (LOption α) := do\n  let b ← x\n  return b.toLOption\n\nend Lean\n","refs":[[19,4,19,8,"2f9f9634f21a",true],[21,11,21,20,"daa69d994416",false],[27,6,27,11,"2f9f9634f21a",false],[29,35,29,41,"848ef6f5f042",false],[30,4,30,9,"2f9f9634f21a",false],[30,15,30,20,"9f8fc0e1929f",false],[31,9,31,14,"507958be0e45",false],[33,36,33,42,"848ef6f5f042",false],[34,4,34,8,"507958be0e45",false],[35,4,35,8,"9f8fc0e1929f",false],[35,14,35,19,"2f9f9634f21a",false],[37,48,37,53,"0cabd2e0ecff",false],[37,65,37,71,"848ef6f5f042",false]]});
